// Valide et nettoie l'input
const sessionId = $input.item.json.session_id;
const message = $input.item.json.message;

if (!sessionId || !message) {
  throw new Error('session_id et message sont obligatoires');
}

return {
  json: {
    session_id: sessionId,
    message: message.trim(),
    timestamp: new Date().toISOString()
  }
};

// Construit l'historique de conversation pour Claude
const existingMessages = $input.all();
const history = [];

// Parcourir messages existants
existingMessages.forEach(msg => {
  if (msg.json.role && msg.json.content) {
    history.push({
      role: msg.json.role,
      content: msg.json.content
    });
  }
});

// Ajouter nouveau message user
history.push({
  role: 'user',
  content: $node['Webhook Chat'].json.message
});

return {
  json: {
    messages: history,
    session_id: $node['Webhook Chat'].json.session_id
  }
};

// Parse la réponse de Claude
const response = $input.item.json;
const messageText = response.content[0].text;

// Tenter de parser le JSON
let parsed;
try {
  parsed = JSON.parse(messageText);
} catch (e) {
  // Fallback si pas JSON
  parsed = {
    message: messageText,
    infos_collectees: {},
    checklist_completion: 0,
    next_action: 'continue',
    urgence: 'normale',
    notes_internes: 'Erreur parsing JSON'
  };
}

// Ajouter session_id pour la suite
parsed.session_id = $node['Webhook Chat'].json.session_id;

return { json: parsed };

