parameters.functionCode:
// Calcule 3 créneaux optimaux selon la zone
const lead = $input.item.json;
const canton = lead.canton;

// Mapping canton → zone
const cantonToZone = {
  'Genève': 'geneve',
  'Vaud': 'lausanne',
  'Valais': 'valais',
  'Fribourg': 'fribourg',
  'Neuchâtel': 'neuchatel',
  'Jura': 'jura'
};

const zone = cantonToZone[canton] || 'lausanne';

// Jours préférés par zone (optimisation planning)
const preferredDays = {
  'geneve': [1, 3, 5],      // Lun, Mer, Ven
  'lausanne': [2, 4],       // Mar, Jeu
  'valais': [3],            // Mer
  'fribourg': [2, 5],       // Mar, Ven
  'neuchatel': [1, 4],      // Lun, Jeu
  'jura': [5]               // Ven
};

// Durée selon type vitrage
const durations = {
  'pare-brise': lead.has_adas ? 90 : 60,
  'vitre-laterale-avant-gauche': 45,
  'vitre-laterale-avant-droite': 45,
  'vitre-laterale-arriere-gauche': 45,
  'vitre-laterale-arriere-droite': 45,
  'lunette-arriere': 45,
  'custode': 30
};

const duration = durations[lead.glass_type] || 60;

// Générer 3 créneaux
const now = new Date();
const slots = [];

for (let i = 1; i <= 14; i++) {
  const date = new Date(now);
  date.setDate(date.getDate() + i);
  const dayOfWeek = date.getDay();

  // Skip dimanche (0) et samedi (6)
  if (dayOfWeek === 0 || dayOfWeek === 6) continue;

  // Priorité aux jours préférés de la zone
  if (preferredDays[zone] && preferredDays[zone].includes(dayOfWeek)) {
    // Créneaux : 9h, 11h, 14h, 16h
    const times = ['09:00', '11:00', '14:00', '16:00'];

    times.forEach(time => {
      const slotDate = new Date(date);
      const [hour, minute] = time.split(':');
      slotDate.setHours(parseInt(hour), parseInt(minute), 0, 0);

      slots.push({
        datetime: slotDate.toISOString(),
        zone: zone,
        display: `${date.toLocaleDateString('fr-CH', {weekday: 'long', day: '2-digit', month: '2-digit'})} à ${time}`,
        duration: duration
      });
    });
  }

  if (slots.length >= 3) break;
}

// Si pas assez de créneaux, ajouter autres jours
if (slots.length < 3) {
  for (let i = 1; i <= 14 && slots.length < 3; i++) {
    const date = new Date(now);
    date.setDate(date.getDate() + i);
    const dayOfWeek = date.getDay();

    if (dayOfWeek === 0 || dayOfWeek === 6) continue;

    const times = ['09:00', '14:00'];
    times.forEach(time => {
      if (slots.length >= 3) return;

      const slotDate = new Date(date);
      const [hour, minute] = time.split(':');
      slotDate.setHours(parseInt(hour), parseInt(minute), 0, 0);

      slots.push({
        datetime: slotDate.toISOString(),
        zone: zone,
        display: `${date.toLocaleDateString('fr-CH', {weekday: 'long', day: '2-digit', month: '2-digit'})} à ${time}`,
        duration: duration
      });
    });
  }
}

return {
  json: {
    lead: lead,
    proposed_slots: slots.slice(0, 3),
    zone: zone,
    duration: duration
  }
};

